from threetears.evals import Eval

from strength import rate

def meter(case):
    """The band the meter shows for the password."""
    return {"band": rate(case["password"], case["username"]).band}


def team_band(case, out):
    """The meter shows the band the security team gave the password."""
    return out["band"] == case["team_band"]

reviewed = Eval("data/reviewed.jsonl", runner=meter, grader=[team_band], k=1)
